{
  "version": 1,
  "jobs": [
    {
      "id": "78f50a18-690a-4667-a12c-99a01398515c",
      "agentId": "main",
      "name": "daily-security-audit",
      "enabled": true,
      "createdAtMs": 1771254363238,
      "schedule": {
        "tz": "Asia/Seoul",
        "expr": "0 3 * * *",
        "kind": "cron"
      },
      "sessionTarget": "isolated",
      "wakeMode": "now",
      "payload": {
        "message": "'openclaw security audit --deep'를 실행하세요. tavily-search(스크립트/extract.mjs, scripts/search.mjs)와 claude-mem(bun-runner.js, context-generator.cjs, mcp-server.cjs, smart-install.js, worker-cli.js) 그리고 writing-skills(render-graphs.js)에서 발생하는 오탐(false positives)은 무시하세요.",
        "kind": "agentTurn",
        "model": "zai/glm-4.7"
      },
      "delivery": {
        "mode": "announce",
        "channel": "telegram",
        "to": "telegram:5487758242"
      },
      "state": {}
    },
    {
      "id": "dc1f52da-a247-4c7c-8ad8-c3f0d5ca71fc",
      "agentId": "main",
      "name": "daily-update-check",
      "enabled": true,
      "createdAtMs": 1771254363249,
      "schedule": {
        "tz": "Asia/Seoul",
        "kind": "cron",
        "expr": "0 6 * * *"
      },
      "sessionTarget": "isolated",
      "wakeMode": "now",
      "payload": {
        "message": "Check for OpenClaw and skills updates using 'openclaw update status' and 'npx skills check'. If updates are available, verify that Telegram channel is synced and notify Sam with the update details.",
        "kind": "agentTurn",
        "model": "zai/glm-4.7"
      },
      "delivery": {
        "mode": "announce",
        "channel": "telegram",
        "to": "telegram:5487758242"
      },
      "state": {}
    },
    {
      "id": "07b6a467-2277-4376-8c4c-b8ae1a7ac74f",
      "agentId": "main",
      "name": "periodic-memory-maintenance",
      "enabled": true,
      "createdAtMs": 1771254363257,
      "schedule": {
        "expr": "0 23 * * 0",
        "kind": "cron",
        "tz": "Asia/Seoul"
      },
      "sessionTarget": "isolated",
      "wakeMode": "now",
      "payload": {
        "kind": "agentTurn",
        "message": "Read through recent memory files in 'workspace/memory/' and distill key learnings, decisions, and context into 'MEMORY.md'. Ensure the long-term memory remains curated and useful."
      },
      "delivery": {
        "mode": "announce"
      },
      "state": {}
    },
    {
      "id": "eb4407c8-7e9a-4d66-b956-2695d5aee260",
      "agentId": "main",
      "name": "daily-morning-briefing",
      "enabled": true,
      "createdAtMs": 1771254363268,
      "schedule": {
        "expr": "0 7 * * *",
        "kind": "cron",
        "tz": "Asia/Seoul"
      },
      "sessionTarget": "isolated",
      "wakeMode": "now",
      "payload": {
        "kind": "agentTurn",
        "message": "It's 7 AM. Provide a morning briefing for Sam: 1. Current weather in Seoul (using weather skill). 2. Brief system status overview. 3. Any urgent notifications or tasks from memory. Keep it sharp and helpful.",
        "model": "zai/glm-4.7"
      },
      "delivery": {
        "mode": "announce",
        "channel": "telegram",
        "to": "telegram:5487758242"
      },
      "state": {}
    },
    {
      "id": "52ed00fd-cb4e-41ec-bde8-8c03c61c3d93",
      "agentId": "main",
      "sessionKey": "agent:main:main",
      "name": "daily-github-backup",
      "enabled": true,
      "createdAtMs": 1771408374779,
      "schedule": {
        "kind": "cron",
        "tz": "Asia/Seoul",
        "expr": "0 4 * * *"
      },
      "sessionTarget": "isolated",
      "wakeMode": "now",
      "payload": {
        "message": "exec 도구로 /home/lfant/.openclaw/workspace/backup_to_github.sh 백업 스크립트를 실행하세요. 실패하면 오류를 보고하고, 성공하면 백업 완료만 확인하세요.",
        "kind": "agentTurn"
      },
      "delivery": {
        "mode": "announce",
        "channel": "telegram",
        "to": "telegram:5487758242"
      },
      "state": {}
    },
    {
      "id": "de62862d-0431-460a-93d4-a21c9c54aa7c",
      "agentId": "main",
      "name": "notion-daily-briefing",
      "enabled": true,
      "createdAtMs": 1772063184622,
      "schedule": {
        "kind": "cron",
        "expr": "0 8 * * *",
        "tz": "Asia/Seoul"
      },
      "sessionTarget": "isolated",
      "wakeMode": "now",
      "payload": {
        "kind": "agentTurn",
        "message": "Run 'python3 /home/lfant/.openclaw/workspace/notion_daily_brief.py'. Then produce a concise Korean briefing for Sam: max 25 items (top priority first), include category counts and immediate actions. Keep under 3500 characters for Telegram delivery.",
        "timeoutSeconds": 300,
        "model": "zai/glm-4.7"
      },
      "delivery": {
        "mode": "announce",
        "channel": "telegram",
        "to": "telegram:5487758242"
      },
      "state": {}
    },
    {
      "id": "0f2e06c5-425c-40b2-845b-135e47277fe1",
      "name": "github-repo-daily-briefing",
      "enabled": true,
      "createdAtMs": 1772414390336,
      "schedule": {
        "kind": "cron",
        "expr": "0 9 * * *",
        "tz": "Asia/Seoul"
      },
      "sessionTarget": "isolated",
      "wakeMode": "now",
      "payload": {
        "kind": "agentTurn",
        "message": "매일 09:00 KST 기준으로 GitHub 인기 레포 브리핑을 생성해 Sam에게 한국어로 전달하세요. 반드시 GitHub API(gh api 또는 공식 REST)로 실제 데이터를 조회하세요. 출력 형식: (1) 최근 인기 Top 5(최근 7일 생성 + stars 기준), (2) 누적 스타 상위 Top 5(archived 제외, 가능하면 최근 활동 있는 레포 우선), (3) 각 레포 핵심 설명 1~2문장(무엇/왜 중요한지), (4) OpenClaw 또는 Claude Code에 바로 적용 가능한 아이디어 3~5개(자동화/보안/개발생산성 관점), (5) 오늘 바로 실행할 액션 3개. 중복 레포는 한 번만 노출하고 전체 2500자 이내로 간결하게 작성하세요.",
        "timeoutSeconds": 300,
        "model": "zai/glm-4.7"
      },
      "delivery": {
        "mode": "announce",
        "channel": "telegram",
        "to": "telegram:5487758242"
      },
      "agentId": "main",
      "state": {}
    },
    {
      "id": "34ae8346-6001-49dd-b83d-17865b2b46c3",
      "name": "workspace-heartbeat",
      "description": "Low-noise workspace heartbeat for session state, cron health, and file-memory continuity",
      "enabled": true,
      "createdAtMs": 1773063542846,
      "schedule": {
        "kind": "cron",
        "expr": "0 9,12,15,18,21 * * *",
        "tz": "Asia/Seoul"
      },
      "sessionTarget": "main",
      "wakeMode": "now",
      "payload": {
        "kind": "systemEvent",
        "text": "Read HEARTBEAT.md if it exists (workspace context). Follow it strictly. Do not infer or repeat old tasks from prior chats. If nothing needs attention, reply HEARTBEAT_OK."
      },
      "state": {}
    }
  ]
}
